async def _acquire_connection(self, timeout: Real = None) -> Connection:
    """Acquire a connection from the pool."""
    try:
        return await aio.wait_for(self._queue.get(), timeout)
    except aio.TimeoutError:
        raise NoConnectionsAvailable("Timeout waiting for a connection")

def __enter__(self) -> 'ConnectionPool':
    if aio.get_event_loop().is_running():
        raise RuntimeError("Use async with inside a running event loop!")
    return self

def _table_name(self, name: AnyStr) -> bytes:
    """Construct a table name by optionally adding a table name prefix."""
    name = ensure_bytes(name)
    if self.table_prefix is None:
        return name
    return self.table_prefix + self.table_prefix_separator + name

def ensure_bytes(value: AnyStr) -> bytes:
    """Convert text into bytes, and leaves bytes as-is."""
    if isinstance(value, bytes):
        return value 
    if isinstance(value, str):
        return value.encode('utf-8')
    raise TypeError(
        f"input must be a text or byte string, got {type(value).__name__}"
    )

def __del__(self) -> None:
    try:
        if self.transport.is_open():
