async def close(self):
    """Clean up all pool connections and delete the queue."""
    while True:
        try:
            await self._queue.get_nowait().close()
        except aio.QueueEmpty:
            break
    del self._queue

def make_row(row: TRowResult, include_timestamp: bool) -> Row:
    """Make a row dict for a given row result."""
    if row.sortedColumns is not None:
        cell_map = {c.columnName: c.cell for c in row.sortedColumns}
    elif row.columns is not None:
        cell_map = row.columns
    else:
        raise RuntimeError("Neither columns nor sortedColumns is available!")
    return {
        name: (cell.value, cell.timestamp) if include_timestamp else cell.value
        for name, cell in cell_map.items()
    }

def __init__(self, name: bytes, connection: 'Connection'):
    self.name = name
    self.connection = connection

def __init__(self, size: int, **kwargs):
    if not isinstance(size, int):
        raise TypeError("Pool 'size' arg must be an integer")

    if not size > 0:
        raise ValueError("Pool 'size' arg must be greater than zero")

    logger.debug(f"Initializing connection pool with {size} connections")

    self._queue = aio.LifoQueue(maxsize=size)
    self._task_connections = {}

    kwargs['autoconnect'] = False

    for i in range(size):
        self._queue.put_nowait(Connection(**kwargs))

async def _column_family_names(self) -> List[bytes]:
    """Retrieve the column family names for this table"""
    return list(await self._column_family_descriptors())

def pep8_to_camel_case(name: str, initial: bool = False) -> str:
    """Convert a PEP8 style name to camel case."""
    chunks = name.split('_')
    converted = [s.capitalize() for s in chunks]
    if initial:
        return ''.join(converted)
    else:
        return chunks[0].lower() + ''.join(converted[1:])

def thrift_attrs(obj_or_cls) -> List[str]:
    """Obtain Thrift data type attribute names for an instance or class."""
    return [v[1] for v in obj_or_cls.thrift_spec.values()]

def thrift_type_to_dict(obj: Any) -> Dict[bytes, Any]:
    """Convert a Thrift data type to a regular dictionary."""
    return {
        camel_case_to_pep8(attr): getattr(obj, attr)
        for attr in thrift_attrs(obj)
    }

def __del__(self) -> None:
